import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  Button,
  Input,
  LeaveConfirmModal,
  LinModalFormShell,
  LinPageLayout,
  Modal,
  SearchInput,
  SearchTextInput,
  dispatchAppToast,
  getActiveCompanyCode,
  getAuthUser,
  useCatalogTableBusy,
  useDirtyTracking,
  useFormLeaveGuard,
  type LinListToolbarActionDef,
} from '@linm-soft-org/linm-web-common-components';
import {
  createAccountSearchConfig,
  type AccountSearchRecord,
} from '../../../components/search';
import { VoucherListPagination } from '../../../components/list/VoucherListPagination';
import {
  createOpeningJobBalance,
  deleteOpeningJobBalance,
  listOpeningJobBalances,
  updateOpeningJobBalance,
  type OpeningJobBalanceListItem,
  type OpeningJobBalanceWriteBody,
} from '../../../services/kt/openingJobBalances';
import { useAppDispatch } from '../../../store/hooks';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import { formatQuantity } from '../../../utils/formatters';
import df from '../../../styles/documentForm.module.css';
import erp from '../../../styles/erpPage.module.css';

const TEST_ID = 'ct-so-du-dau-nam-cong-trinh';
const PAGE_ID = 'kt-so-du-dau-nam-cong-trinh';
const TITLE = 'Cập nhập số dư đầu năm của các công trình';
const AMOUNT_RE = /^-?\d{1,16}$|^-?\d{1,16}\.\d{1,4}$/;
const LEAVE_MESSAGE = 'Có thay đổi chưa được lưu. Đóng form sẽ mất dữ liệu đã nhập.';

type FormMode = 'create' | 'edit';
type SelectionMode = 'keep' | 'clear' | 'prefer';

interface FormState {
  id?: string;
  year: string;
  accountCode: string;
  jobCode: string;
  currencyCode: string;
  debitBalance: string;
  creditBalance: string;
  debitBalanceFc: string;
  creditBalanceFc: string;
}

function sessionCompany(): string {
  return (getActiveCompanyCode() ?? getAuthUser()?.companyCode ?? '').trim();
}

function emptyForm(): FormState {
  return {
    year: String(new Date().getFullYear()),
    accountCode: '',
    jobCode: '',
    currencyCode: '',
    debitBalance: '',
    creditBalance: '',
    debitBalanceFc: '',
    creditBalanceFc: '',
  };
}

function amountToInput(value: number): string {
  if (!Number.isFinite(value)) return '';
  return String(value);
}

function formFromRow(row: OpeningJobBalanceListItem, keepId: boolean): FormState {
  return {
    id: keepId ? row.id : undefined,
    year: String(row.year),
    accountCode: row.accountCode ?? '',
    jobCode: row.jobCode ?? '',
    currencyCode: row.currencyCode ?? '',
    debitBalance: amountToInput(row.debitBalance),
    creditBalance: amountToInput(row.creditBalance),
    debitBalanceFc: amountToInput(row.debitBalanceFc),
    creditBalanceFc: amountToInput(row.creditBalanceFc),
  };
}

function parseWhole(raw: string, min: number, max: number): number | null {
  const text = raw.trim();
  if (!/^\d+$/.test(text)) return null;
  const value = Number(text);
  if (!Number.isInteger(value) || value < min || value > max) return null;
  return value;
}

function parseAmount(raw: string): number | null {
  const text = raw.trim().replace(/\s/g, '').replace(/,/g, '.');
  if (text === '') return 0;
  if (!AMOUNT_RE.test(text)) return null;
  const value = Number(text);
  return Number.isFinite(value) ? value : null;
}

const SoDuDauNamCongTrinhPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const accountSearch = useMemo(() => createAccountSearchConfig(), []);
  const { onDirtyChange, guardedNavigate, leaveConfirmModalProps } = useFormLeaveGuard({
    message: LEAVE_MESSAGE,
  });
  const { markDirty, markClean } = useDirtyTracking(onDirtyChange);

  const [items, setItems] = useState<OpeningJobBalanceListItem[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(50);
  const [yearFilter, setYearFilter] = useState(String(new Date().getFullYear()));
  const [yearApplied, setYearApplied] = useState(new Date().getFullYear());
  const [searchDraft, setSearchDraft] = useState('');
  const [searchApplied, setSearchApplied] = useState('');
  const [loading, setLoading] = useState(false);
  const [reloadKey, setReloadKey] = useState(0);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [mode, setMode] = useState<FormMode | null>(null);
  const [form, setForm] = useState<FormState>(emptyForm);
  const [banner, setBanner] = useState('');
  const [saving, setSaving] = useState(false);
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const selectionMode = useRef<SelectionMode>('keep');
  const preferId = useRef<string | null>(null);

  const { showTableLoading } = useCatalogTableBusy(loading);
  const selected = items.find(row => row.id === selectedId) ?? null;

  useEffect(() => {
    const company = sessionCompany();
    if (!company) {
      setItems([]);
      setTotalCount(0);
      setSelectedId(null);
      dispatchAppToast(dispatch, { message: 'Không xác định đơn vị', type: 'error' });
      return;
    }

    let cancelled = false;
    setLoading(true);
    listOpeningJobBalances({
      year: yearApplied,
      page,
      pageSize,
      search: searchApplied || undefined,
    })
      .then(data => {
        if (cancelled) return;
        const rows = data.items ?? [];
        setItems(rows);
        setTotalCount(data.totalCount ?? 0);
        setSelectedId(prev => {
          if (selectionMode.current === 'clear') return null;
          if (selectionMode.current === 'prefer') {
            const id = preferId.current;
            if (id && rows.some(row => row.id === id)) return id;
          }
          return prev && rows.some(row => row.id === prev) ? prev : null;
        });
        selectionMode.current = 'keep';
      })
      .catch(err => {
        if (cancelled) return;
        setItems([]);
        setTotalCount(0);
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không tải được số dư đầu năm công trình'),
          type: 'error',
        });
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [dispatch, page, pageSize, searchApplied, yearApplied, reloadKey]);

  const touch = (patch: Partial<FormState>) => {
    markDirty();
    setBanner('');
    setForm(prev => ({ ...prev, ...patch }));
  };

  const closeForm = useCallback(() => {
    setMode(null);
    setBanner('');
    markClean();
  }, [markClean]);

  const openCreate = useCallback(() => {
    setForm(emptyForm());
    setBanner('');
    setMode('create');
    markClean();
  }, [markClean]);

  const openEdit = useCallback(() => {
    if (!selected) return;
    setForm(formFromRow(selected, true));
    setBanner('');
    setMode('edit');
    markClean();
  }, [markClean, selected]);

  const openCopy = useCallback(() => {
    if (!selected) return;
    setForm(formFromRow(selected, false));
    setBanner('');
    setMode('create');
    markClean();
  }, [markClean, selected]);

  const validateForm = (): string | null => {
    if (!sessionCompany()) return 'Không xác định đơn vị';
    if (parseWhole(form.year, 0, 9999) == null) return 'Nhập năm';
    if (form.accountCode.trim().length > 30) return 'Nhập tài khoản';
    if (form.jobCode.trim().length > 30) return 'Nhập mã vụ việc';
    if (form.currencyCode.trim().length > 10) return 'Nhập ngoại tệ';
    if (parseAmount(form.debitBalance) == null) return 'Nhập số';
    if (parseAmount(form.creditBalance) == null) return 'Nhập số';
    if (parseAmount(form.debitBalanceFc) == null) return 'Nhập số';
    if (parseAmount(form.creditBalanceFc) == null) return 'Nhập số';
    return null;
  };

  const handleSave = async () => {
    const message = validateForm();
    if (message) {
      setBanner(message);
      return;
    }
    const year = parseWhole(form.year, 0, 9999);
    const debitBalance = parseAmount(form.debitBalance);
    const creditBalance = parseAmount(form.creditBalance);
    const debitBalanceFc = parseAmount(form.debitBalanceFc);
    const creditBalanceFc = parseAmount(form.creditBalanceFc);
    if (
      year == null
      || debitBalance == null
      || creditBalance == null
      || debitBalanceFc == null
      || creditBalanceFc == null
    ) return;

    const body: OpeningJobBalanceWriteBody = {
      year,
      accountCode: form.accountCode.trim(),
      jobCode: form.jobCode.trim(),
      currencyCode: form.currencyCode.trim(),
      debitBalance,
      creditBalance,
      debitBalanceFc,
      creditBalanceFc,
    };

    setSaving(true);
    try {
      const saved = mode === 'edit' && form.id
        ? await updateOpeningJobBalance(form.id, { ...body, id: form.id })
        : await createOpeningJobBalance(body);
      dispatchAppToast(dispatch, { message: 'Đã lưu số dư đầu năm công trình', type: 'success' });
      selectionMode.current = 'prefer';
      preferId.current = saved?.id ?? null;
      markClean();
      setMode(null);
      setBanner('');
      setReloadKey(key => key + 1);
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: getApiErrorMessage(err, 'Lưu thất bại'),
        type: 'error',
      });
    } finally {
      setSaving(false);
    }
  };

  const confirmDelete = async () => {
    if (!selected) return;
    setDeleting(true);
    try {
      await deleteOpeningJobBalance(selected.id);
      dispatchAppToast(dispatch, { message: 'Đã xóa số dư đầu năm công trình', type: 'success' });
      selectionMode.current = 'clear';
      setSelectedId(null);
      setDeleteOpen(false);
      setReloadKey(key => key + 1);
    } catch (err) {
      setDeleteOpen(false);
      dispatchAppToast(dispatch, {
        message: getApiErrorMessage(err, 'Xóa thất bại'),
        type: 'error',
      });
    } finally {
      setDeleting(false);
    }
  };

  const commitYearFilter = useCallback((nextSearch?: string): boolean => {
    const year = parseWhole(yearFilter, 0, 9999);
    if (year == null) {
      dispatchAppToast(dispatch, { message: 'Nhập năm', type: 'error' });
      return false;
    }
    setYearFilter(String(year));
    setYearApplied(year);
    if (nextSearch !== undefined) setSearchApplied(nextSearch);
    setPage(1);
    setReloadKey(key => key + 1);
    return true;
  }, [dispatch, yearFilter]);

  const handleYearCommit = useCallback(() => {
    commitYearFilter();
  }, [commitYearFilter]);

  const handleSearch = useCallback(() => {
    commitYearFilter(searchDraft.trim());
  }, [commitYearFilter, searchDraft]);

  const handleRefresh = useCallback(() => {
    const year = parseWhole(yearFilter, 0, 9999);
    if (year == null) {
      dispatchAppToast(dispatch, { message: 'Nhập năm', type: 'error' });
      return;
    }
    setYearFilter(String(year));
    setYearApplied(year);
    setReloadKey(key => key + 1);
  }, [dispatch, yearFilter]);

  const toolbarActions = useMemo((): LinListToolbarActionDef[] => [
    {
      id: 'refresh',
      placement: 'left',
      action: 'refresh',
      visible: true,
      disabled: loading,
      onClick: handleRefresh,
      testId: `${TEST_ID}-toolbar-refresh-btn`,
    },
    {
      id: 'add',
      placement: 'right',
      action: 'create',
      label: 'Thêm',
      variant: 'primary',
      visible: true,
      onClick: openCreate,
      testId: `${TEST_ID}-toolbar-add-btn`,
    },
    {
      id: 'edit',
      placement: 'right',
      action: 'edit',
      visible: true,
      disabled: !selected || loading,
      onClick: openEdit,
      testId: `${TEST_ID}-toolbar-edit-btn`,
    },
    {
      id: 'copy',
      placement: 'right',
      action: 'copy',
      visible: true,
      disabled: !selected || loading,
      onClick: openCopy,
      testId: `${TEST_ID}-toolbar-copy-btn`,
    },
    {
      id: 'delete',
      placement: 'right',
      action: 'delete',
      visible: true,
      disabled: !selected || loading,
      onClick: () => setDeleteOpen(true),
      testId: `${TEST_ID}-toolbar-delete-btn`,
    },
  ], [handleRefresh, loading, openCopy, openCreate, openEdit, selected]);

  const listBody = showTableLoading ? null : items.length === 0 ? (
    <div className={erp.empty} data-testid={`${TEST_ID}-empty`}>
      {searchApplied === ''
        ? 'Không có số dư đầu năm công trình'
        : 'Không tìm thấy số dư đầu năm công trình'}
    </div>
  ) : (
    <div className={erp.tableWrapper}>
      <table className={erp.table} data-testid={`${TEST_ID}-grid`}>
        <thead>
          <tr>
            <th>Đơn vị</th>
            <th>Tài khoản</th>
            <th>Vụ việc</th>
            <th>Tên vụ việc</th>
            <th className={erp.colRight}>Dư nợ</th>
            <th className={erp.colRight}>Dư có</th>
            <th className={erp.colRight}>Dư nợ NT</th>
            <th className={erp.colRight}>Dư có NT</th>
          </tr>
        </thead>
        <tbody>
          {items.map(row => (
            <tr
              key={row.id}
              data-testid={`${TEST_ID}-row-${row.id}`}
              className={row.id === selectedId ? erp.rowSelected : undefined}
              onClick={() => setSelectedId(row.id)}
            >
              <td>{row.companyCode}</td>
              <td>{row.accountCode}</td>
              <td>{row.jobCode}</td>
              <td>{row.jobName}</td>
              <td className={erp.colRight}>{formatQuantity(row.debitBalance, 4)}</td>
              <td className={erp.colRight}>{formatQuantity(row.creditBalance, 4)}</td>
              <td className={erp.colRight}>{formatQuantity(row.debitBalanceFc, 4)}</td>
              <td className={erp.colRight}>{formatQuantity(row.creditBalanceFc, 4)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );

  return (
    <div className={erp.catalogListRoot} data-testid={`${TEST_ID}-list`}>
      <LinPageLayout
        kind="catalog"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        pageClassName={erp.catalogListPage}
        header={{
          title: TITLE,
          pageId: PAGE_ID,
        }}
        listTitle={TITLE}
        toolbarProps={{
          testIdPrefix: TEST_ID,
          profile: 'catalog',
          actions: toolbarActions,
        }}
        filters={(
          <div style={{ display: 'flex', gap: 12, alignItems: 'flex-end', flexWrap: 'wrap' }}>
            <div className={erp.field}>
              <label className={df.label} htmlFor={`${TEST_ID}-filter-year`}>Năm</label>
              <Input
                id={`${TEST_ID}-filter-year`}
                data-testid={`${TEST_ID}-filter-year`}
                inputMode="numeric"
                value={yearFilter}
                onChange={e => setYearFilter(e.target.value)}
                onBlur={handleYearCommit}
                onKeyDown={e => {
                  if (e.key === 'Enter') {
                    e.preventDefault();
                    handleYearCommit();
                  }
                }}
              />
            </div>
            <SearchTextInput
              label="Tìm kiếm"
              value={searchDraft}
              onChange={setSearchDraft}
              onSearch={handleSearch}
              placeholder="Tìm tài khoản, vụ việc, số dư..."
              testId={`${TEST_ID}-search-text`}
            />
          </div>
        )}
        showTableLoading={showTableLoading}
        skeletonRows={8}
        footer={(
          <VoucherListPagination
            testIdPrefix={TEST_ID}
            page={page}
            totalCount={totalCount}
            pageSize={pageSize}
            onPageChange={setPage}
            onPageSizeChange={size => {
              setPageSize(size);
              setPage(1);
            }}
          />
        )}
        modals={(
          <>
            <LinModalFormShell
              formId={TEST_ID}
              testIdPrefix={TEST_ID}
              size="md"
              isOpen={mode != null}
              title={mode === 'edit'
                ? 'Sửa số dư đầu năm công trình'
                : 'Thêm số dư đầu năm công trình'}
              onClose={() => guardedNavigate(closeForm)}
              footerActions={[
                {
                  id: 'cancel',
                  label: 'Hủy',
                  variant: 'secondary',
                  onClick: () => guardedNavigate(closeForm),
                  testId: `${TEST_ID}-cancel-btn`,
                },
                {
                  id: 'save',
                  label: 'Lưu',
                  variant: 'primary',
                  disabled: saving,
                  onClick: () => { void handleSave(); },
                  testId: `${TEST_ID}-save-btn`,
                },
              ]}
            >
              {banner ? (
                <div className={df.errorBanner} data-testid={`${TEST_ID}-form-error`}>{banner}</div>
              ) : null}
              <div className={df.row4}>
                <div className={df.field}>
                  <label className={df.label} htmlFor={`${TEST_ID}-field-year`}>
                    Năm<span className={df.requiredMark}>*</span>
                  </label>
                  <Input
                    id={`${TEST_ID}-field-year`}
                    data-testid={`${TEST_ID}-field-year`}
                    value={form.year}
                    onChange={e => touch({ year: e.target.value })}
                  />
                </div>
                <div className={df.field} data-testid={`${TEST_ID}-field-accountCode`}>
                  <span className={df.label}>Tài khoản</span>
                  <SearchInput
                    config={accountSearch}
                    value={form.accountCode}
                    primaryDisplay={form.accountCode}
                    showLabel={false}
                    showSecondaryInput={false}
                    placeholder="Tài khoản"
                    onChange={(item: AccountSearchRecord) => touch({ accountCode: item.code })}
                    onClear={() => touch({ accountCode: '' })}
                  />
                </div>
                <div className={df.field}>
                  <label className={df.label} htmlFor={`${TEST_ID}-field-jobCode`}>
                    Vụ việc
                  </label>
                  <Input
                    id={`${TEST_ID}-field-jobCode`}
                    data-testid={`${TEST_ID}-field-jobCode`}
                    maxLength={30}
                    value={form.jobCode}
                    onChange={e => touch({ jobCode: e.target.value })}
                  />
                </div>
              </div>
              <div className={df.row4}>
                <div className={df.field}>
                  <label className={df.label} htmlFor={`${TEST_ID}-field-currencyCode`}>
                    Ngoại tệ
                  </label>
                  <Input
                    id={`${TEST_ID}-field-currencyCode`}
                    data-testid={`${TEST_ID}-field-currencyCode`}
                    maxLength={10}
                    value={form.currencyCode}
                    onChange={e => touch({ currencyCode: e.target.value })}
                  />
                </div>
                <div className={df.field}>
                  <label className={df.label} htmlFor={`${TEST_ID}-field-debitBalance`}>
                    Dư nợ
                  </label>
                  <Input
                    id={`${TEST_ID}-field-debitBalance`}
                    data-testid={`${TEST_ID}-field-debitBalance`}
                    inputMode="decimal"
                    value={form.debitBalance}
                    onChange={e => touch({ debitBalance: e.target.value })}
                  />
                </div>
                <div className={df.field}>
                  <label className={df.label} htmlFor={`${TEST_ID}-field-creditBalance`}>
                    Dư có
                  </label>
                  <Input
                    id={`${TEST_ID}-field-creditBalance`}
                    data-testid={`${TEST_ID}-field-creditBalance`}
                    inputMode="decimal"
                    value={form.creditBalance}
                    onChange={e => touch({ creditBalance: e.target.value })}
                  />
                </div>
              </div>
              <div className={df.row4}>
                <div className={df.field}>
                  <label className={df.label} htmlFor={`${TEST_ID}-field-debitBalanceFc`}>
                    Dư nợ NT
                  </label>
                  <Input
                    id={`${TEST_ID}-field-debitBalanceFc`}
                    data-testid={`${TEST_ID}-field-debitBalanceFc`}
                    inputMode="decimal"
                    value={form.debitBalanceFc}
                    onChange={e => touch({ debitBalanceFc: e.target.value })}
                  />
                </div>
                <div className={df.field}>
                  <label className={df.label} htmlFor={`${TEST_ID}-field-creditBalanceFc`}>
                    Dư có NT
                  </label>
                  <Input
                    id={`${TEST_ID}-field-creditBalanceFc`}
                    data-testid={`${TEST_ID}-field-creditBalanceFc`}
                    inputMode="decimal"
                    value={form.creditBalanceFc}
                    onChange={e => touch({ creditBalanceFc: e.target.value })}
                  />
                </div>
              </div>
            </LinModalFormShell>
            <Modal
              isOpen={deleteOpen}
              size="sm"
              title="Xóa số dư đầu năm công trình đã chọn?"
              onClose={() => {
                if (!deleting) setDeleteOpen(false);
              }}
            >
              <div data-testid={`${TEST_ID}-delete-modal`}>
                <p>Xóa số dư đầu năm công trình đã chọn?</p>
                <Button
                  variant="secondary"
                  data-testid={`${TEST_ID}-delete-cancel-btn`}
                  disabled={deleting}
                  onClick={() => setDeleteOpen(false)}
                >
                  Hủy
                </Button>
                <Button
                  variant="primary"
                  data-testid={`${TEST_ID}-delete-confirm-btn`}
                  disabled={deleting}
                  onClick={() => { void confirmDelete(); }}
                >
                  Xóa
                </Button>
              </div>
            </Modal>
            <LeaveConfirmModal {...leaveConfirmModalProps} />
          </>
        )}
      >
        {listBody}
      </LinPageLayout>
    </div>
  );
};

export default SoDuDauNamCongTrinhPage;
