import { apiClient, unwrap, type BffResponse } from '../api';

export interface OpeningJobBalanceListItem {
  id: string;
  year: number;
  companyCode: string;
  accountCode: string;
  jobCode: string;
  jobName: string;
  currencyCode: string;
  debitBalance: number;
  creditBalance: number;
  debitBalanceFc: number;
  creditBalanceFc: number;
}

export interface OpeningJobBalancePage {
  items: OpeningJobBalanceListItem[];
  totalCount: number;
  page: number;
  pageSize: number;
}

export interface OpeningJobBalanceWriteBody {
  year: number;
  accountCode: string;
  jobCode: string;
  currencyCode: string;
  debitBalance: number;
  creditBalance: number;
  debitBalanceFc: number;
  creditBalanceFc: number;
}

export interface OpeningJobBalanceUpdateBody extends OpeningJobBalanceWriteBody {
  id: string;
}

export async function listOpeningJobBalances(query: {
  year: number;
  page: number;
  pageSize: number;
  search?: string;
}): Promise<OpeningJobBalancePage> {
  const qs = new URLSearchParams();
  qs.set('year', String(query.year));
  qs.set('page', String(query.page));
  qs.set('pageSize', String(query.pageSize));
  const search = query.search?.trim() ?? '';
  if (search) qs.set('search', search);
  const res = await apiClient.get<BffResponse<OpeningJobBalancePage>>(
    `/accounting/opening-job-balances?${qs.toString()}`,
  );
  return unwrap(res);
}

export async function createOpeningJobBalance(
  body: OpeningJobBalanceWriteBody,
): Promise<OpeningJobBalanceListItem> {
  const res = await apiClient.post<BffResponse<OpeningJobBalanceListItem>>(
    '/accounting/opening-job-balances',
    body,
  );
  return unwrap(res);
}

export async function updateOpeningJobBalance(
  id: string,
  body: OpeningJobBalanceUpdateBody,
): Promise<OpeningJobBalanceListItem> {
  const res = await apiClient.put<BffResponse<OpeningJobBalanceListItem>>(
    `/accounting/opening-job-balances/${encodeURIComponent(id)}`,
    body,
  );
  return unwrap(res);
}

export async function deleteOpeningJobBalance(id: string): Promise<boolean> {
  const res = await apiClient.delete<BffResponse<boolean>>(
    `/accounting/opening-job-balances/${encodeURIComponent(id)}`,
  );
  return unwrap(res);
}
